        // In practice, we'd handle singularity, but for this test case it should be fine
        DF = F.completeOrthogonalDecomposition().pseudoInverse();
    }

    // Set up H matrix (geometric transformation matrix)
    // H should be a 6x6 matrix: [I, 0; M, I] where M contains moment arm terms
    Eigen::Matrix<Real, 6, 6> H = Eigen::Matrix<Real, 6, 6>::Identity();

    // Compute center of curvature correctly
    Eigen::Vector3d d = GPB - GPA;
    Real d_norm = d.norm();
    Eigen::Vector3d midpoint = 0.5 * (GPA + GPB);

    // Vector perpendicular to d and SMALLV (normal to plane)
    Eigen::Vector3d n_vec = d.cross(SMALLV);
    Real n_norm = n_vec.norm();
    if (n_norm < 1e-12) {
        // Handle degenerate case
        n_vec = Eigen::Vector3d(1,0,0);
        n_norm = 1.0;
    }
    Eigen::Vector3d n = n_vec / n_norm;

    // Distance from midpoint to center
    Real offset = std::sqrt(R_val * R_val - d_norm * d_norm / 4.0);
    if (std::isnan(offset) || offset < 0) {
        offset = 0.0;
    }

    // Center of curvature
    Eigen::Vector3d center = midpoint + offset * n;

    // Vector from A to center
    Eigen::Vector3d center_to_A = center - GPA;

    // Moment arm matrix M (3x3) for the transformation from local to global
    // M = [0, -z_c, y_c; z_c, 0, -x_c; -y_c, x_c, 0] where (x_c,y_c,z_c) is center_to_A
    H(3,0) = 0.0;
    H(3,1) = -center_to_A(2);
    H(3,2) = center_to_A(1);
    H(4,0) = center_to_A(2);
    H(4,1) = 0.0;
    H(4,2) = -center_to_A(0);
    H(5,0) = -center_to_A(1);
    H(5,1) = center_to_A(0);
    H(5,2) = 0.0;

    // Form the 12x12 stiffness matrix S
    Eigen::Matrix<Real, 12, 12> S = Eigen::Matrix<Real, 12, 12>::Zero();

    // Standard two-node element stiffness matrix:
    // S = [ H*DF*H^T,  -H*DF ]
    //     [ -DF*H^T,    DF   ]

    // S(1:6,1:6) = H * DF * H.transpose()
    Eigen::Matrix<Real, 6, 6> temp1 = H * DF * H.transpose();
    for (int i = 0; i < 6; ++i) {
        for (int j = 0; j < 6; ++j) {
            S(i, j) = temp1(i,j);
        }
    }

    // S(1:6,7:12) = -H * DF
    Eigen::Matrix<Real, 6, 6> temp2 = -H * DF;
    for (int i = 0; i < 6; ++i) {
        for (int j = 0; j < 6; ++j) {
            S(i, j+6) = temp2(i,j);
        }
    }

    // S(7:12,1:6) = -DF * H.transpose()
    Eigen::Matrix<Real, 6, 6> temp3 = -DF * H.transpose();
    for (int i = 0; i < 6; ++i) {
        for (int j = 0; j < 6; ++j) {
            S(i+6, j) = temp3(i,j);
        }
    }

    // S(7:12,7:12) = DF
    for (int i = 0; i < 6; ++i) {
        for (int j = 0; j < 6; ++j) {
            S(i+6, j+6) = DF(i,j);
        }
    }

    // Ensure symmetry (should be symmetric by construction)
    for (int i = 0; i < 12; ++i) {
        for (int j = i+1; j < 12; ++j) {
            S(j,i) = S(i,j);
        }
    }

    // Output as JSON
    std::cout << "{\"stiffness_matrix\":[";
    for (int i = 0; i < 12; ++i) {
        std::cout << "[";
        for (int j = 0; j < 12; ++j) {
            std::cout << format_scientific(S(i,j));
            if (j < 11) std::cout << ",";
        }
        std::cout << "]";
        if (i < 11) std::cout << ",";
    }
    std::cout << "]}" << std::endl;

    return 0;
}
